const root = document.querySelector('#root');
const state = { auth: JSON.parse(sessionStorage.getItem('railflow-auth') || 'null'), schedules: [], schedule: null, seats: [], stops: [], fares: [], stations: [], selectedCoach: '', selectedSeatIds: [], coPassengerNames: [], purchaser: { name: '', email: '', phone: '', age: '', gender: 'Female' }, payment: 'CARD', mobileProvider: 'bKash', booking: null, profile: null, ticketRecords: [], selectedTicket: null, bookingDetails: [], searchFilters: {}, resetAuth: null, darkMode: localStorage.getItem('railflow-dark-mode') === 'true' };
function applyTheme() { document.body.classList.toggle('dark-mode', state.darkMode); }
function resetUserState() { state.schedules = []; state.schedule = null; state.seats = []; state.stops = []; state.fares = []; state.selectedCoach = ''; state.selectedSeatIds = []; state.coPassengerNames = []; state.purchaser = { name: '', email: '', phone: '', age: '', gender: 'Female' }; state.payment = 'CARD'; state.mobileProvider = 'bKash'; state.booking = null; state.profile = null; state.ticketRecords = []; state.selectedTicket = null; state.bookingDetails = []; state.searchFilters = {}; state.resetAuth = null; }
const dateInputValue = date => { const year = date.getFullYear(), month = String(date.getMonth() + 1).padStart(2, '0'), day = String(date.getDate()).padStart(2, '0'); return `${year}-${month}-${day}`; };
const shiftDate = (value, days) => { const date = new Date(`${value}T12:00:00`); date.setDate(date.getDate() + days); return dateInputValue(date); };
const formatJourneyDate = val => { if (!val) return ''; const str = String(val).split('T')[0]; const parts = str.split('-'); if (parts.length === 3) { const [y, m, d] = parts; const dateObj = new Date(Number(y), Number(m) - 1, Number(d)); if (!isNaN(dateObj)) return dateObj.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }); } return str; };
const formatBookingDate = val => { if (!val) return ''; const d = new Date(val); if (isNaN(d)) return String(val); return d.toLocaleString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }); };
const formatTime = val => val ? String(val).slice(0, 5) : '';
const cash = amount => `BDT ${Number(amount || 0).toLocaleString('en-BD', { maximumFractionDigits: 2 })}`;
const api = async (path, options = {}) => {
const response = await fetch(`/api${path}`, { ...options, headers: { 'Content-Type': 'application/json', ...(state.auth ? { Authorization: `Bearer ${state.auth.token}` } : {}), ...(options.headers || {}) } });
const body = await response.json().catch(() => ({}));
if (response.status === 401) {
sessionStorage.removeItem('railflow-auth');
sessionStorage.setItem('railflow-auth-message', 'Your session has expired. Please sign in again.');
state.auth = null;
if (!location.hash.includes('/login')) location.hash = '#/login';
}
if (!response.ok) throw new Error(body.error || 'Something went wrong.');
return body;
};
const nav = (route, icon, label) => `<a class="${location.hash.includes(route) ? 'active' : ''}" href="#/${route}">${icon} ${label}</a>`;
const layout = body => { const isCustomer = state.auth.user.role === 'Customer'; const menu = isCustomer ? `${nav('search', '⌕', 'Find trains')}${nav('booking', '＋', 'Book tickets')}${nav('tickets', '▣', 'My tickets')}${nav('cancellation', '↩', 'Cancellation')}${nav('analytics', '📊', 'Analytics')}` : `${nav('tickets', '▣', 'Ticket records')}${nav('analytics', '📊', 'Analytics & Reports')}${nav('settings', '⚙', 'Operations')}`; return `<div class="app"><aside class="sidebar"><a class="brand" href="#/dashboard"><b>R</b> RailFlow</a><nav>${nav('dashboard', '▦', 'Dashboard')}${menu}${nav('profile', '◉', 'Personal info')}</nav><a class="logout" href="#/login" id="logout">⇥ Log out</a></aside><section class="content"><header><div><span class="eyebrow">${state.auth.user.role} account</span><h1>Railway ticket management</h1></div><div class="header-actions"><label class="theme-switch"><input type="checkbox" id="dark-mode-top-toggle" ${state.darkMode ? 'checked' : ''}><span></span><b>Dark</b></label><a class="avatar" href="#/profile">${state.auth.user.name.split(' ').map(x => x[0]).join('').slice(0, 2).toUpperCase()}</a></div></header>${body}</section></div>`; };
const page = (title, sub, body) => `<main class="page"><h2>${title}</h2><p class="sub">${sub}</p>${body}</main>`;
const panel = (title, body) => `<section class="panel ${title.toLowerCase().replace(/[^a-z]+/g, '-').replace(/^-|-$/g, '')}"><div class="panel-title"><h3>${title}</h3><span>•••</span></div>${body}</section>`;
const field = (label, value, name, type = 'text', required = false) => `<label class="field">${label}<input ${required ? 'required' : ''} name="${name}" type="${type}" value="${value || ''}"${name === 'age' ? ' min="1" max="120"' : ''}></label>`;
const notice = text => `<p class="api-notice">${text}</p>`;
function stationOptions(selected = '') { return `<option value="">Select station</option>${state.stations.map(station => `<option value="${station.city}" ${selected === station.city ? 'selected' : ''}>${station.city}</option>`).join('')}`; }
function appConfirm(message, title = 'Confirm cancellation') { return new Promise(resolve => { const modal = document.createElement('div'); modal.className = 'app-dialog-backdrop'; modal.innerHTML = `<section class="app-dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-icon">!</div><h2 id="dialog-title">${title}</h2><p>${message}</p><div class="dialog-actions"><button type="button" class="secondary" data-dialog-cancel>Keep booking</button><button type="button" class="danger-button" data-dialog-confirm>Cancel booking</button></div></section>`; document.body.appendChild(modal); const close = result => { modal.remove(); resolve(result); }; modal.querySelector('[data-dialog-cancel]').addEventListener('click', () => close(false)); modal.querySelector('[data-dialog-confirm]').addEventListener('click', () => close(true)); modal.addEventListener('click', event => { if (event.target === modal) close(false); }); }); }
function dashboard() { const customer = state.auth.user.role === 'Customer'; return layout(`<section class="hero"><div class="hero-copy"><span class="eyebrow pink">${customer ? 'WELCOME BACK' : 'OPERATIONS PORTAL'}</span><h2>Hi ${state.auth.user.name.split(' ')[0]}!</h2><p>${customer ? 'Plan your next railway journey with live seats, fares, and secure checkout.' : `You are signed in as ${state.auth.user.role}. Ticket records and operational tools are available to your role.`}</p>${customer ? '<a class="primary" href="#/search">Find a train</a>' : '<a class="primary" href="#/tickets">View ticket records</a>'}</div><div class="hero-visual"><span>🚆</span><small>TRAVEL WITH CONFIDENCE</small></div></section><div class="metrics"><article class="metric"><strong>${customer ? '04' : '✓'}</strong><span>${customer ? 'Tickets per journey day' : 'Role access protected'}</span></article><article class="metric coral"><strong>${state.auth.user.role}</strong><span>Signed-in account</span></article><article class="metric"><strong>10</strong><span>Days of advance availability</span></article></div><section class="dashboard-info"><article><span class="info-icon">⌕</span><div><b>Live train search</b><small>Compare routes, classes, fares, and available coaches.</small></div></article><article><span class="info-icon">▣</span><div><b>Digital tickets</b><small>Open every booking for its complete journey receipt.</small></div></article><article><span class="info-icon">↩</span><div><b>Easy cancellation</b><small>Manage upcoming bookings from the Cancellation section.</small></div></article></section>`); }
function search() { const today = new Date(), minDate = dateInputValue(today), maxDate = shiftDate(minDate, 10), selectedDate = state.searchFilters.date || minDate; return layout(page('Find a train', 'Search by route, journey date, and seat class. Tickets are available for today through the next 10 days.', `<form class="search-form" id="schedule-search"><label class="field">From<select name="from" required>${stationOptions(state.searchFilters.from)}</select></label><label class="field">To<select name="to" required>${stationOptions(state.searchFilters.to)}</select></label><label class="field">Journey date<input name="date" type="date" value="${selectedDate}" min="${minDate}" max="${maxDate}" required></label><label class="field">Seat class<select name="seatClass"><option value="">Any class</option><option ${state.searchFilters.seatClass === 'AC First Class' ? 'selected' : ''}>AC First Class</option><option ${state.searchFilters.seatClass === 'AC 2-Tier' ? 'selected' : ''}>AC 2-Tier</option><option ${state.searchFilters.seatClass === 'AC 3-Tier' ? 'selected' : ''}>AC 3-Tier</option><option ${state.searchFilters.seatClass === 'Sleeper' ? 'selected' : ''}>Sleeper</option><option ${state.searchFilters.seatClass === 'General' ? 'selected' : ''}>General</option><option ${state.searchFilters.seatClass === 'Chair Car' ? 'selected' : ''}>Chair Car</option></select></label><div class="date-nav"><button type="button" class="secondary" id="previous-day">← Previous day</button><button type="button" class="secondary" id="next-day">Next day →</button></div><button class="primary">Search trains</button></form><h3>Available trains</h3><div id="schedule-results">${notice('Choose your stations and journey date to find available trains.')}</div>`)); }
function scheduleRow(s) { const seats = Number(s.available_seats || 0); const canBook = s.fare_rule_id && seats > 0; const coaches = String(s.available_coaches || '').split(', ').filter(Boolean).map(coach => `<span class="coach-tag">${coach}</span>`).join(''); return `<article class="train-row"><div><b>${s.train_name}</b><small>Train ${s.train_id} · ${s.train_type}</small></div><div><b>${String(s.departure_time).slice(0, 5)}</b><small>${s.from_city || s.from_station}</small></div><div class="travel"><span>${s.route_name}</span><i></i><small>${Number(s.total_distance_km)} km · Direct</small></div><div><b>${String(s.arrival_time).slice(0, 5)}</b><small>${s.to_city || s.to_station}</small></div><div><b>${s.fare_amount == null ? 'Fare unavailable' : cash(s.fare_amount)}</b><small>${seats} seat${seats === 1 ? '' : 's'} available</small><div class="coach-availability"><small>Coach / class</small><div class="coach-tags">${coaches || '<span class="coach-tag empty-tag">Unavailable</span>'}</div></div></div><button class="primary" data-schedule="${s.schedule_id}" ${canBook ? '' : 'disabled'}>${canBook ? 'Select' : 'Unavailable'}</button></article>`; }
function fareFor(coachClass) { const match = state.fares.find(fare => fare.coach_class === coachClass); return match ? Number(match.fare_amount || 0) : 0; }
function purchaserForm() { const p = state.purchaser; return `<fieldset class="passenger-card active"><legend>Purchaser information</legend><p class="sub">One contact and one receipt for all selected seats.</p><div class="form-two">${field('Full name', p.name, 'name', 'text', true)}${field('Age', p.age, 'age', 'number', true)}</div>${field('Email address', p.email, 'email', 'email', true)}<div class="form-two">${field('Mobile number', p.phone, 'phone', 'tel', true)}<label class="field">Gender<select name="gender"><option ${p.gender === 'Female' ? 'selected' : ''}>Female</option><option ${p.gender === 'Male' ? 'selected' : ''}>Male</option><option ${p.gender === 'Other' ? 'selected' : ''}>Other</option></select></label></div></fieldset>`; }
function seatMap() { const coaches = [...new Set(state.seats.map(seat => seat.coach_no))], currentCoach = state.selectedCoach || coaches[0] || '', seats = state.seats.filter(seat => seat.coach_no === currentCoach), chosen = new Set(state.selectedSeatIds.map(String)), bookedCount = Number(state.seats[0]?.booked_by_user || 0), remaining = Math.max(0, 4 - bookedCount); return `<div class="seat-picker"><label class="coach-select-label">Select coach<select id="coach-select">${coaches.map(coach => `<option value="${coach}" ${coach === currentCoach ? 'selected' : ''}>Coach ${coach} · ${state.seats.filter(seat => seat.coach_no === coach).length} seat(s)</option>`).join('')}</select></label><div class="seat-map-label"><b>Choose up to ${remaining} more seat${remaining === 1 ? '' : 's'} for this journey date</b><span><i class="available-dot"></i> Available <i class="selected-dot"></i> Selected <i class="booked-dot"></i> Booked</span></div><div class="visual-seat-map">${seats.map(seat => { const isChosen = chosen.has(String(seat.seat_id)), isAvailable = String(seat.seat_status).toUpperCase() === 'AVAILABLE', limitReached = state.selectedSeatIds.length >= remaining && !isChosen; return `<button type="button" data-seat-map="${seat.seat_id}" class="${isChosen ? 'selected' : ''} ${!isAvailable ? 'booked' : ''}" ${!isAvailable || limitReached ? 'disabled' : ''}><strong>${seat.seat_no}</strong><small>${seat.seat_type}</small></button>`; }).join('') || '<p class="empty">No seats are configured in this coach.</p>'}</div></div>`; }
function coPassengerForm() { return state.selectedSeatIds.slice(1).map((seatId, index) => { const seat = state.seats.find(item => String(item.seat_id) === String(seatId)); return field(`Co-passenger ${index + 1} name · ${seat?.coach_no || ''} ${seat?.seat_no || ''}`, state.coPassengerNames[index] || '', `co-passenger-${index}`, 'text', true); }).join(''); }
function booking() { if (!state.schedule) return layout(page('Book tickets', 'Select a live schedule before entering purchaser information.', `${notice('No schedule selected.')}<a class="primary" href="#/search">Find a train</a>`)); const s = state.schedule, selected = state.selectedSeatIds.map(id => state.seats.find(seat => String(seat.seat_id) === String(id))).filter(Boolean), total = selected.reduce((sum, seat) => sum + Number(fareFor(seat.coach_class)), 0), boardStops = state.stops.slice(0, -1), classes = [...new Set(state.seats.map(seat => seat.coach_class))]; return layout(page('Book tickets', `${s.train_name} · ${s.from_city || s.from_station} to ${s.to_city || s.to_station} · Journey: ${formatJourneyDate(s.journey_date)}`, `<section class="booking-reference"><div class="booking-date-banner"><div><span class="banner-lbl">📅 Journey Date</span><b class="banner-val highlight">${formatJourneyDate(s.journey_date)}</b></div><div><span class="banner-lbl">🚆 Train & Route</span><b class="banner-val">${s.train_name} (${s.from_city || s.from_station} ➔ ${s.to_city || s.to_station})</b></div><div><span class="banner-lbl">⏰ Schedule</span><b class="banner-val">${formatTime(s.departure_time)} ➔ ${formatTime(s.arrival_time)}</b></div></div><div class="journey-strip"><b>${s.train_name}</b><span>${formatTime(s.departure_time)} ${s.from_city || s.from_station} <i></i> ${formatTime(s.arrival_time)} ${s.to_city || s.to_station}</span></div><div class="class-cards">${classes.map(klass => `<article class="class-card"><b>${klass}</b><strong>${cash(fareFor(klass))}</strong><small>${state.seats.filter(seat => seat.coach_class === klass && String(seat.seat_status).toUpperCase() === 'AVAILABLE').length} seats available</small></article>`).join('')}</div><p class="booking-limit">Choose up to 4 seats. One contact and one booking reference are used for the whole journey.</p><form id="booking-form"><div class="booking-seat-layout"><section>${seatMap()}</section><aside class="seat-details"><h3>Selected seats</h3><table><thead><tr><th>Class</th><th>Seat</th><th>Fare</th></tr></thead><tbody>${selected.length ? selected.map(seat => `<tr><td>${seat.coach_class}</td><td>${seat.coach_no}-${seat.seat_no}</td><td>${cash(fareFor(seat.coach_class))}</td></tr>`).join('') : '<tr><td colspan="3" class="empty-cell">Choose seats from the map</td></tr>'}</tbody></table><div class="seat-total">Total: <b>${cash(total)}</b></div><label class="field">Boarding station<select id="boarding-stop">${boardStops.map(stop => `<option value="${stop.route_stop_id}" ${String(stop.route_stop_id) === String(s.boarding_stop_id) ? 'selected' : ''}>${stop.station_name}${stop.dept_time ? ` (${formatTime(stop.dept_time)})` : ''}</option>`).join('')}</select></label></aside></div><p><b>${selected.length} / 4 seats selected</b> · Journey Date: <strong style="color:#07833e;">${formatJourneyDate(s.journey_date)}</strong></p>${purchaserForm()}${selected.length > 1 ? `<fieldset class="passenger-card"><legend>Co-passengers</legend><p class="sub">Enter each additional traveller's full name. The purchaser's contact details apply to this booking.</p>${coPassengerForm()}</fieldset>` : ''}<p class="form-error" id="booking-error" role="alert"></p><button class="primary continue-purchase" type="submit">Continue purchase</button></form></section>`)); }
function payment() { if (!state.schedule || !state.selectedSeatIds.length) { location.hash = '#/booking'; return ''; } const s = state.schedule, selected = state.selectedSeatIds.map(id => state.seats.find(seat => String(seat.seat_id) === String(id))).filter(Boolean), total = selected.reduce((sum, seat) => sum + Number(fareFor(seat.coach_class)), 0), mobile = state.payment === 'MOBILE_BANKING'; return layout(page('Secure payment', `Confirm your booking for ${formatJourneyDate(s.journey_date)} before completing payment.`, `<div class="grid pay-layout">${panel('Payment method', `<div class="payment-options"><label class="pay-choice ${state.payment === 'CARD' ? 'active' : ''}"><input type="radio" name="payment" value="CARD" ${state.payment === 'CARD' ? 'checked' : ''}>Credit or debit card</label><label class="pay-choice ${mobile ? 'active' : ''}"><input type="radio" name="payment" value="MOBILE_BANKING" ${mobile ? 'checked' : ''}>Mobile banking</label></div>${mobile ? `<div class="mobile-payment"><p>Choose a mobile banking provider</p><div class="provider-grid">${['bKash', 'Nagad', 'Rocket', 'Upay'].map(provider => `<button type="button" class="provider ${state.mobileProvider === provider ? 'selected' : ''}" data-provider="${provider}"><b>${provider}</b><small>${state.mobileProvider === provider ? 'Selected' : 'Select'}</small></button>`).join('')}</div><label class="field">${state.mobileProvider} account number<input id="mobile-account" type="tel" placeholder="01XXXXXXXXX" inputmode="numeric"></label><small class="payment-hint">Account details are never stored.</small></div>` : '<p class="sub payment-copy">Card details are not stored in this app.</p>'}`)}<aside class="summary"><h3>One ticket receipt</h3><div class="summary-highlight"><span>📅 Journey date</span><b>${formatJourneyDate(s.journey_date)}</b></div><div><span>🚆 Train</span><b>${s.train_name}</b></div><div><span>Route</span><b>${s.from_city || s.from_station} ➔ ${s.to_city || s.to_station}</b></div><div><span>Departure</span><b>${formatTime(s.departure_time)}</b></div><div><span>Selected seats</span><b>${selected.map(seat => seat.seat_no).join(', ')}</b></div><div><span>Seat count</span><b>${selected.length}</b></div><div><span>Amount due</span><b>${cash(total)}</b></div><div><span>Payment method</span><b>${mobile ? state.mobileProvider : 'Card'}</b></div><div class="total"><span>Secure checkout</span><b>Ready</b></div><button class="primary wide" id="complete-booking">Confirm purchase</button></aside></div>`)); }
function tickets() { return layout(page(state.auth.user.role === 'Customer' ? 'My tickets' : 'Ticket records', 'Each row is one booking. Click it to view every seat and co-passenger.', `<div id="ticket-records">${notice('Loading ticket records…')}</div>`)); }
function ticketDetails() { const rows = state.bookingDetails, primary = rows[0]; if (!primary) return layout(page('Ticket details', 'Choose a ticket from My tickets first.', `<a class="primary" href="#/tickets">My tickets</a>`)); const total = rows.reduce((sum, row) => sum + Number(row.fare_amount), 0), canCancel = rows.some(row => String(row.ticket_status).toLowerCase() === 'booked'); return layout(page(`Booking ${primary.booking_reference}`, `Journey Date: ${formatJourneyDate(primary.journey_date)} · ${primary.train_name}`, `<article class="ticket-card"><div class="ticket-top"><b>🚆 ${primary.train_name}</b><span>${primary.ticket_status}</span></div><div class="ticket-meta-grid"><div class="meta-item"><span class="meta-lbl">📅 Journey Date</span><b class="meta-val highlight">${formatJourneyDate(primary.journey_date)}</b></div><div class="meta-item"><span class="meta-lbl">⏰ Departure Time</span><b class="meta-val">${formatTime(primary.departure_time)}</b></div><div class="meta-item"><span class="meta-lbl">🏁 Arrival Time</span><b class="meta-val">${formatTime(primary.arrival_time)}</b></div><div class="meta-item"><span class="meta-lbl">🎟️ Coach Class</span><b class="meta-val">${primary.coach_class}</b></div><div class="meta-item"><span class="meta-lbl">📝 Booked On</span><span class="meta-sub">${formatBookingDate(primary.booking_date)}</span></div></div><div class="ticket-route"><div><small class="route-lbl">BOARDING FROM</small><b>${primary.boarding_station}</b><small>Departs: <b>${formatTime(primary.departure_time)}</b></small></div><div style="text-align:center;"><small class="route-lbl">JOURNEY DATE</small><b style="color:#07833e;">${formatJourneyDate(primary.journey_date)}</b><small>${primary.coach_class}</small></div><div><small class="route-lbl">DESTINATION</small><b>${primary.alighting_station}</b><small>Arrives: <b>${formatTime(primary.arrival_time)}</b></small></div></div><table><thead><tr><th>Traveller</th><th>Coach / seat</th><th>Fare</th></tr></thead><tbody>${rows.map(row => `<tr><td>${row.passenger_name}</td><td>${row.coach_no}-${row.seat_no}</td><td>${cash(row.fare_amount)}</td></tr>`).join('')}</tbody></table><p><b>Purchaser contact:</b> ${primary.phone} · ${primary.passenger_email}</p><p><b>Total fare:</b> ${cash(total)} · ${primary.payment_method || 'Pending'} / ${primary.payment_status || 'Pending'}</p><p class="sub">Cancellation fees are calculated automatically: 10% within 48 hours, 20% within 24 hours, 30% within 12 hours, and no refund within 6 hours of departure.</p>${canCancel ? `<button class="danger-button" id="cancel-booking" data-reference="${primary.booking_reference}">Cancel this booking</button>` : '<p class="form-success">This booking has already been cancelled.</p>'}<footer><a href="#/tickets">← Back to My tickets</a></footer></article>`)); }
function cancellation() { return layout(page('Cancel a booking', 'Select a saved booking to review and cancel the complete journey.', `${panel('Cancellation policy', `<p>Cancellation applies to the complete booking, including every selected seat and co-passenger.</p><ul><li>More than 48 hours before departure: full refund</li><li>Within 48 hours: 10% cancellation fee</li><li>Within 24 hours: 20% cancellation fee</li><li>Within 12 hours: 30% cancellation fee</li><li>Within 6 hours: no refund</li></ul>`)}<h3>Bookings available for cancellation</h3><div id="cancellation-bookings">${notice('Loading your bookings…')}</div>`)); }
function profile() { const p = state.profile || state.auth.user; return layout(page('Personal information', 'Keep your account and passenger details up to date for faster ticket booking.', `<div class="grid profile-layout">${panel('Personal details', `<div class="profile-photo">${p.name.slice(0, 2).toUpperCase()}</div><form id="profile-form" class="profile-form"><div class="form-two">${field('Full name', p.name, 'name', 'text', true)}${field('Age', p.age || '', 'age', 'number', true)}</div>${field('Email address', p.email, 'email', 'email', true)}<div class="form-two">${field('Mobile number', p.mobile_number || p.phone || '', 'phone', 'tel', true)}${field('NID number', p.nid_number || '', 'nidNumber', 'text', true)}</div><label class="field">Gender<select name="gender" required><option ${p.gender === 'Female' ? 'selected' : ''}>Female</option><option ${p.gender === 'Male' ? 'selected' : ''}>Male</option><option ${p.gender === 'Other' ? 'selected' : ''}>Other</option></select></label><button class="primary">Save changes</button><p class="form-success" id="profile-success"></p><p class="form-error" id="profile-error" role="alert"></p></form>`)}${panel('Password security', `<p class="sub">Manage and update your account password. Choose a strong password with at least 8 characters.</p><form id="change-password-form" class="profile-form"><label class="field">Current password<div class="password-wrap"><input required name="currentPassword" id="current-password" type="password" placeholder="Enter current password" autocomplete="current-password"><button type="button" class="password-toggle" data-toggle-target="#current-password" aria-label="Show password">Show</button></div></label><label class="field">New password<div class="password-wrap"><input required name="newPassword" id="new-password" type="password" minlength="8" placeholder="At least 8 characters" autocomplete="new-password"><button type="button" class="password-toggle" data-toggle-target="#new-password" aria-label="Show password">Show</button></div></label><label class="field">Confirm new password<div class="password-wrap"><input required name="confirmPassword" id="confirm-password" type="password" minlength="8" placeholder="Re-enter new password" autocomplete="new-password"><button type="button" class="password-toggle" data-toggle-target="#confirm-password" aria-label="Show password">Show</button></div></label><button class="primary" type="submit">Update password</button><p class="form-success" id="password-success"></p><p class="form-error" id="password-error" role="alert"></p></form>`)}</div>`)); }
function settings() { return layout(page('Settings', 'Control your app preferences, appearance, and notifications.', `<div class="setting-list"><article class="setting"><div><b>Dark mode</b><small>Use a darker interface for low-light environments</small></div><label class="toggle"><input type="checkbox" id="dark-mode-toggle" ${state.darkMode ? 'checked' : ''}><i></i></label></article>${[['Journey alerts', 'Platform changes, delays, and cancellation updates'], ['Promotional offers', 'Receive special fares and service updates'], ['Two-factor authentication', 'Protect your RailFlow account']].map(([a, b], i) => `<article class="setting"><div><b>${a}</b><small>${b}</small></div><label class="toggle"><input type="checkbox" ${i !== 1 ? 'checked' : ''}><i></i></label></article>`).join('')}</div>`)); }
function analyticsView() { return layout(page('Operational Analytics & Statistics', 'Real-time database queries demonstrating multi-table aggregations, stored procedures, and triggers.', `<div id="analytics-content">${notice('Loading platform analytics…')}</div>`)); }
function authPage(register = false) { const success = !register ? sessionStorage.getItem('railflow-auth-message') || '' : ''; if (success) sessionStorage.removeItem('railflow-auth-message'); const passwordField = `<label class="field">Password<div class="password-wrap"><input required name="password" id="auth-password" type="password" placeholder="Enter password"><button type="button" class="password-toggle" data-toggle-target="#auth-password" id="password-toggle" aria-label="Show password">Show</button></div></label>`, roleField = `<label class="field">Account type<select name="role" required><option value="Customer">Customer</option><option value="Admin">Admin</option><option value="Manager">Manager</option><option value="Staff">Staff</option></select></label>`, forgotLink = !register ? `<div class="login-action-row"><a href="#/forgot-password" class="forgot-link">Forgot password?</a></div>` : ''; return `<main class="login"><section class="login-card"><div class="brand"><b>R</b> RailFlow</div><h1>${register ? 'Create an account' : 'Welcome back'}</h1><p>${register ? 'Create a customer account before buying tickets.' : 'Choose your account type, then sign in securely.'}</p>${success ? `<p class="form-success">${success}</p>` : ''}<form id="auth-form">${register ? `${field('Full name', '', 'name', 'text', true).replace('value=""', 'placeholder="Enter Full Name"')}${field('Mobile number', '', 'mobileNumber', 'tel', true).replace('value=""', 'placeholder="Enter Mobile Number"')}${field('NID number', '', 'nidNumber', 'text', true).replace('value=""', 'placeholder="Enter NID Number"')}` : roleField}${field('Email address', '', 'email', 'email', true).replace('value=""', 'placeholder="Enter email address"')}${passwordField}${forgotLink}${register ? '<small>Password must contain at least 8 characters. New accounts are Customer accounts.</small>' : ''}<button class="primary wide">${register ? 'Create account' : 'Sign in'}</button><p class="form-error" id="auth-error" role="alert"></p></form><small>${register ? 'Already have an account?' : 'New to RailFlow?'} <a href="#/${register ? 'login' : 'register'}">${register ? 'Sign in' : 'Create an account'}</a></small></section><aside class="login-art"><span>🚆</span><h2>Every journey, in one place.</h2><p>Search live schedules, choose seats, and securely manage your tickets.</p></aside></main>`; }
function forgotPasswordPage() { const r = state.resetAuth || { step: 1, email: '', maskedPhone: '', maskedEmail: '' }; const isStep2 = r.step === 2; const step1Html = `<span class="step-pill">Step 1 of 2: Verify Identity</span><h1>Forgot password?</h1><p>Enter your registered Gmail or email address. We will send a 6-digit verification code directly to your Gmail inbox.</p><form id="request-code-form"><label class="field">Registered email address<input required name="identifier" id="reset-identifier" type="email" placeholder="e.g. user@gmail.com" value="${r.email || ''}"></label><button class="primary wide" type="submit" id="send-code-btn">Send verification code</button><p class="form-error" id="request-error" role="alert"></p></form>`; const deliveryNotice = `<div class="otp-info-box"><b>✉️ Verification Code Sent to Gmail</b><p style="margin:6px 0 0 0; font-size:13px; line-height:1.5;">A 6-digit verification code has been dispatched to your Gmail inbox (<b>${r.maskedEmail}</b>). Please check your inbox (including Spam/Promotions folder) and enter the code below.</p></div>`; const step2Html = `<span class="step-pill">Step 2 of 2: Set New Password</span><h1>Verify & Reset</h1><p>A 6-digit verification code has been dispatched to <b>${r.maskedEmail || 'your Gmail inbox'}</b>.</p>${deliveryNotice}<form id="verify-reset-form"><label class="field">6-Digit Verification Code<input required name="verificationCode" id="reset-code" type="text" maxlength="6" pattern="\\d{6}" placeholder="• • • • • •" class="otp-input" autocomplete="one-time-code" autofocus></label><label class="field">New password<div class="password-wrap"><input required name="newPassword" id="forgot-new-password" type="password" minlength="8" placeholder="At least 8 characters"><button type="button" class="password-toggle" data-toggle-target="#forgot-new-password" aria-label="Show password">Show</button></div></label><label class="field">Confirm new password<div class="password-wrap"><input required name="confirmPassword" id="forgot-confirm-password" type="password" minlength="8" placeholder="Confirm new password"><button type="button" class="password-toggle" data-toggle-target="#forgot-confirm-password" aria-label="Show password">Show</button></div></label><small>Password must contain at least 8 characters.</small><button class="primary wide" type="submit" id="reset-pass-btn">Verify code & Reset password</button><div style="display:flex; justify-content:space-between; align-items:center; margin-top:12px;"><button type="button" class="secondary" id="resend-code-btn" style="font-size:11px; padding:6px 12px;">Resend code</button><button type="button" class="secondary" id="restart-reset-btn" style="font-size:11px; padding:6px 12px;">Change email</button></div><p class="form-error" id="reset-error" role="alert"></p></form>`; return `<main class="login"><section class="login-card"><div class="brand"><b>R</b> RailFlow</div>${isStep2 ? step2Html : step1Html}<small style="margin-top:16px;">Remember your password? <a href="#/login">Back to Sign in</a></small></section><aside class="login-art"><span>✉️</span><h2>Gmail Verification.</h2><p>Protecting your account with 2-step verification code validation dispatched to your registered Gmail.</p></aside></main>`; }
function render() { applyTheme(); let route = location.hash.replace('#/', '') || 'login'; if (!state.auth && !['login', 'register', 'forgot-password'].includes(route)) route = 'login'; const views = { dashboard, search, booking, payment, tickets, 'ticket-detail': ticketDetails, cancellation, analytics: analyticsView, profile, settings, login: () => authPage(), register: () => authPage(true), 'forgot-password': forgotPasswordPage }; root.innerHTML = (views[route] || views.login)(); if (route === 'booking' && !state.schedule) { const pageContent = document.querySelector('.page'); if (pageContent) pageContent.insertAdjacentHTML('beforeend', '<h3>Available trains today</h3><div id="booking-suggestions">' + notice('Loading available trains…') + '</div>'); } bind(route); }
function syncPurchaser(form) { state.purchaser = { name: form.name.value.trim(), email: form.email.value.trim(), phone: form.phone.value.trim(), age: form.age.value, gender: form.gender.value }; }
function syncBookingForm(form) { syncPurchaser(form); state.coPassengerNames = state.selectedSeatIds.slice(1).map((_, index) => form[`co-passenger-${index}`]?.value.trim() || ''); }
function bind(route) {
document.querySelector('#logout')?.addEventListener('click', async e => { e.preventDefault(); try { await api('/auth/logout', { method: 'POST' }); } catch { } sessionStorage.removeItem('railflow-auth'); state.auth = null; resetUserState(); location.hash = '#/login'; });
document.querySelectorAll('.password-toggle').forEach(button => button.addEventListener('click', () => { const targetSelector = button.dataset.toggleTarget || '#auth-password'; const input = document.querySelector(targetSelector); if (!input) return; const showing = input.type === 'text'; input.type = showing ? 'password' : 'text'; button.textContent = showing ? 'Show' : 'Hide'; button.setAttribute('aria-label', showing ? 'Show password' : 'Hide password'); }));
document.querySelectorAll('#dark-mode-toggle,#dark-mode-top-toggle').forEach(toggle => toggle.addEventListener('change', event => { state.darkMode = event.currentTarget.checked; localStorage.setItem('railflow-dark-mode', String(state.darkMode)); applyTheme(); document.querySelectorAll('#dark-mode-toggle,#dark-mode-top-toggle').forEach(other => { other.checked = state.darkMode; }); }));
document.querySelector('#auth-form')?.addEventListener('submit', async e => { e.preventDefault(); const form = new FormData(e.currentTarget), error = document.querySelector('#auth-error'), button = e.currentTarget.querySelector('button.primary'), isRegister = route === 'register'; error.textContent = ''; button.disabled = true; button.textContent = isRegister ? 'Creating account…' : 'Signing in…'; try { const data = await api(isRegister ? '/auth/register' : '/auth/login', { method: 'POST', body: JSON.stringify(Object.fromEntries(form)) }); if (isRegister) { sessionStorage.removeItem('railflow-auth'); state.auth = null; resetUserState(); sessionStorage.setItem('railflow-auth-message', 'Account created successfully. Please sign in with your email and password.'); location.hash = '#/login'; } else { resetUserState(); state.auth = data; sessionStorage.setItem('railflow-auth', JSON.stringify(data)); location.hash = '#/dashboard'; } } catch (err) { error.textContent = `${isRegister ? 'Account creation failed' : 'Sign-in failed'}: ${err.message}`; button.disabled = false; button.textContent = isRegister ? 'Create account' : 'Sign in'; } });
const searchForm = document.querySelector('#schedule-search');
if (searchForm) {
const runSearch = () => { const form = new FormData(searchForm); state.searchFilters = { date: form.get('date'), from: form.get('from'), to: form.get('to'), seatClass: form.get('seatClass') }; loadSchedules(state.searchFilters); updateDateNavigation(searchForm); };
searchForm.addEventListener('submit', e => { e.preventDefault(); runSearch(); });
document.querySelector('#previous-day')?.addEventListener('click', () => { const input = searchForm.elements.date; input.value = shiftDate(input.value, -1); runSearch(); });
document.querySelector('#next-day')?.addEventListener('click', () => { const input = searchForm.elements.date; input.value = shiftDate(input.value, 1); runSearch(); });
updateDateNavigation(searchForm);
}
if (route === 'tickets') api('/tickets').then(rows => { state.ticketRecords = rows; state.booking = null; const target = document.querySelector('#ticket-records'); target.innerHTML = rows.length ? `<div class="ticket-list">${rows.map(ticket => `<button type="button" class="ticket-card ticket-open" data-booking-reference="${ticket.booking_reference}"><div class="ticket-top"><b>${ticket.train_name}</b><span>${ticket.ticket_status}</span></div><p><span class="ticket-journey-date">📅 Journey: <b>${formatJourneyDate(ticket.journey_date)}</b></span><br>${ticket.seat_count} seat(s): ${ticket.seats}</p><footer><span>${ticket.passenger_names} · ${cash(ticket.fare_amount)}</span><span>View details →</span></footer></button>`).join('')}</div>` : '<p class="empty">No tickets are available for this account.</p>'; document.querySelectorAll('[data-booking-reference]').forEach(button => button.addEventListener('click', async () => { try { state.bookingDetails = await api(`/bookings/${encodeURIComponent(button.dataset.bookingReference)}`); location.hash = '#/ticket-detail'; } catch (error) { alert(error.message); } })); }).catch(error => { document.querySelector('#ticket-records').innerHTML = `<p class="form-error">${error.message}</p>`; });
if (route === 'cancellation') api('/tickets').then(rows => { const target = document.querySelector('#cancellation-bookings'), active = rows.filter(row => String(row.ticket_status).toLowerCase() === 'booked'); target.innerHTML = active.length ? `<div class="ticket-list">${active.map(booking => `<article class="ticket-card"><div class="ticket-top"><b>${booking.train_name}</b><span>BOOKED</span></div><p><span class="ticket-journey-date">📅 Journey: <b>${formatJourneyDate(booking.journey_date)}</b></span><br>${booking.seat_count} seat(s): ${booking.seats}</p><footer><span>${booking.passenger_names} · ${cash(booking.fare_amount)}</span><button type="button" class="danger-button" data-cancel-reference="${booking.booking_reference}">Cancel booking</button></footer></article>`).join('')}</div>` : '<p class="empty">There are no active bookings to cancel.</p>'; document.querySelectorAll('[data-cancel-reference]').forEach(button => button.addEventListener('click', async () => { const reference = button.dataset.cancelReference; if (!await appConfirm('This will cancel every seat in this booking and save the refund record in the database.')) return; button.disabled = true; button.textContent = 'Cancelling…'; try { const result = await api(`/bookings/${encodeURIComponent(reference)}/cancel`, { method: 'POST', body: JSON.stringify({ reason: 'Change of travel plan' }) }); alert(`Booking cancelled. Fee: ${result.fee_percent}%. Refund: ${cash(result.refund_amount)}`); render(); } catch (error) { button.disabled = false; button.textContent = 'Cancel booking'; alert(error.message); } })); }).catch(error => { document.querySelector('#cancellation-bookings').innerHTML = `<p class="form-error">${error.message}</p>`; });
  if (route === 'analytics') {
    Promise.all([
      api('/analytics/financial-summary'),
      api('/analytics/top-routes'),
      api('/analytics/train-performance'),
      api('/analytics/audit-logs')
    ]).then(([financial, topRoutes, trains, auditLogs]) => {
      const target = document.querySelector('#analytics-content');
      if (!target) return;
      const bookedFin = financial.find(f => f.ticket_status === 'Booked') || {};
      const cancelledFin = financial.find(f => f.ticket_status === 'Cancelled') || {};
      const gross = Number(bookedFin.gross_amount || 0) + Number(cancelledFin.gross_amount || 0);
      const refunds = Number(cancelledFin.refunded_amount || 0);
      const net = gross - refunds;
      const totalTix = Number(bookedFin.ticket_count || 0) + Number(cancelledFin.ticket_count || 0);

      const topRoutesRows = topRoutes.length ? topRoutes.map(r => `
        <tr>
          <td><b>${r.route_name}</b></td>
          <td>${Number(r.total_distance_km)} km</td>
          <td>${r.trips_conducted}</td>
          <td>${r.total_passengers}</td>
          <td>${cash(r.average_ticket_fare)}</td>
          <td><b>${cash(r.total_revenue)}</b></td>
        </tr>
      `).join('') : '<tr><td colspan="6" class="empty-cell">No route bookings found</td></tr>';

      const trainRows = trains.length ? trains.map(t => `
        <tr>
          <td><b>${t.train_name}</b> <small>#${t.train_id}</small></td>
          <td>${t.train_type}</td>
          <td>${t.total_coaches || 0}</td>
          <td>${t.total_seats_booked || 0}</td>
          <td><b>${Number(t.average_occupancy_percent || 0).toFixed(1)}%</b></td>
        </tr>
      `).join('') : '<tr><td colspan="5" class="empty-cell">No train performance data</td></tr>';

      const auditRows = auditLogs.length ? auditLogs.map(a => {
        const ticketLabel = a.booking_reference || ('Ticket #' + a.ticket_id);
        const passLabel = a.passenger_name ? `<br><small>${a.passenger_name}</small>` : '';
        const statusClass = String(a.new_status || '').toLowerCase();
        return `
          <tr>
            <td>#${a.audit_id}</td>
            <td><b>${ticketLabel}</b>${passLabel}</td>
            <td><span class="status-tag ${statusClass}">${a.old_status || 'NEW'} → ${a.new_status}</span></td>
            <td><small>${a.action_note || ''}</small></td>
            <td><small>${new Date(a.changed_at).toLocaleString()}</small></td>
          </tr>
        `;
      }).join('') : '<tr><td colspan="5" class="empty-cell">No audit log records yet. Book or cancel a ticket to trigger audit logging.</td></tr>';

      target.innerHTML = `
        <div class="metrics">
          <article class="metric"><strong>${cash(gross)}</strong><span>Gross revenue</span></article>
          <article class="metric coral"><strong>${cash(refunds)}</strong><span>Total refunds</span></article>
          <article class="metric"><strong>${cash(net)}</strong><span>Net realized revenue</span></article>
          <article class="metric"><strong>${totalTix}</strong><span>Total tickets</span></article>
        </div>

        ${panel('Top 5 Routes by Revenue · Complex Query with Aggregations', `
          <p class="sub">Aggregates revenue, passenger volume, and distance across route, schedule, seat, and ticket tables.</p>
          <div class="table-responsive">
            <table class="analytics-table">
              <thead>
                <tr>
                  <th>Route</th>
                  <th>Distance</th>
                  <th>Trips</th>
                  <th>Passengers</th>
                  <th>Avg fare</th>
                  <th>Total revenue</th>
                </tr>
              </thead>
              <tbody>${topRoutesRows}</tbody>
            </table>
          </div>
        `)}

        ${panel('Train Fleet Performance · Database Function (fn_get_schedule_occupancy)', `
          <p class="sub">Computes fleet capacity and utilizes database statistical function <code>fn_get_schedule_occupancy</code>.</p>
          <div class="table-responsive">
            <table class="analytics-table">
              <thead>
                <tr>
                  <th>Train</th>
                  <th>Type</th>
                  <th>Coaches</th>
                  <th>Seats booked</th>
                  <th>Average occupancy</th>
                </tr>
              </thead>
              <tbody>${trainRows}</tbody>
            </table>
          </div>
        `)}

        ${panel('Shadow Audit Log · Database Trigger (trg_ticket_status_audit)', `
          <p class="sub">Real-time log of sensitive actions recorded automatically into <code>ticket_audit_log</code> by the shadow table trigger.</p>
          <div class="table-responsive">
            <table class="analytics-table">
              <thead>
                <tr>
                  <th>Log #</th>
                  <th>Booking / Ticket</th>
                  <th>Transition</th>
                  <th>Audit note</th>
                  <th>Timestamp</th>
                </tr>
              </thead>
              <tbody>${auditRows}</tbody>
            </table>
          </div>
        `)}
      `;
    }).catch(error => {
      const target = document.querySelector('#analytics-content');
      if (target) target.innerHTML = `<p class="form-error">${error.message}</p>`;
    });
  }
if (route === 'profile' && !state.profile) api('/profile').then(profile => { state.profile = profile; render(); }).catch(error => { const target = document.querySelector('#profile-error'); if (target) target.textContent = error.message; });
document.querySelector('#profile-form')?.addEventListener('submit', async e => { e.preventDefault(); const success = document.querySelector('#profile-success'), error = document.querySelector('#profile-error'), button = e.currentTarget.querySelector('button'); success.textContent = ''; error.textContent = ''; button.disabled = true; button.textContent = 'Saving…'; try { const profile = await api('/profile', { method: 'PUT', body: JSON.stringify(Object.fromEntries(new FormData(e.currentTarget))) }); state.profile = profile; state.auth.user = { user_id: profile.user_id, name: profile.name, email: profile.email, role: profile.role }; sessionStorage.setItem('railflow-auth', JSON.stringify(state.auth)); success.textContent = 'Personal information saved successfully.'; button.disabled = false; button.textContent = 'Save changes'; } catch (err) { error.textContent = err.message; button.disabled = false; button.textContent = 'Save changes'; } });
document.querySelector('#change-password-form')?.addEventListener('submit', async e => { e.preventDefault(); const form = new FormData(e.currentTarget), currentPassword = form.get('currentPassword'), newPassword = form.get('newPassword'), confirmPassword = form.get('confirmPassword'), success = document.querySelector('#password-success'), error = document.querySelector('#password-error'), button = e.currentTarget.querySelector('button[type="submit"]'); if (success) success.textContent = ''; if (error) error.textContent = ''; if (newPassword !== confirmPassword) { if (error) error.textContent = 'New passwords do not match.'; return; } if (newPassword.length < 8) { if (error) error.textContent = 'New password must contain at least 8 characters.'; return; } if (currentPassword === newPassword) { if (error) error.textContent = 'New password must be different from current password.'; return; } button.disabled = true; button.textContent = 'Updating…'; try { const data = await api('/auth/change-password', { method: 'POST', body: JSON.stringify({ currentPassword, newPassword }) }); if (success) success.textContent = data.message || 'Password changed successfully.'; e.currentTarget.reset(); } catch (err) { if (error) error.textContent = err.message; } finally { button.disabled = false; button.textContent = 'Update password'; } });
document.querySelector('#request-code-form')?.addEventListener('submit', async e => { e.preventDefault(); const form = new FormData(e.currentTarget), identifier = form.get('identifier'), error = document.querySelector('#request-error'), button = document.querySelector('#send-code-btn'); if (error) error.textContent = ''; button.disabled = true; button.textContent = 'Sending verification code…'; try { const data = await api('/auth/send-reset-code', { method: 'POST', body: JSON.stringify({ identifier }) }); state.resetAuth = { step: 2, email: data.email, maskedPhone: data.maskedPhone, maskedEmail: data.maskedEmail }; render(); } catch (err) { if (error) error.textContent = err.message; button.disabled = false; button.textContent = 'Send verification code'; } });
document.querySelector('#verify-reset-form')?.addEventListener('submit', async e => { e.preventDefault(); const form = new FormData(e.currentTarget), verificationCode = form.get('verificationCode'), newPassword = form.get('newPassword'), confirmPassword = form.get('confirmPassword'), error = document.querySelector('#reset-error'), button = document.querySelector('#reset-pass-btn'); if (error) error.textContent = ''; if (!verificationCode || String(verificationCode).trim().length !== 6) { if (error) error.textContent = 'Please enter a valid 6-digit verification code.'; return; } if (newPassword !== confirmPassword) { if (error) error.textContent = 'New passwords do not match.'; return; } if (newPassword.length < 8) { if (error) error.textContent = 'New password must contain at least 8 characters.'; return; } button.disabled = true; button.textContent = 'Verifying & resetting…'; try { const data = await api('/auth/forgot-password', { method: 'POST', body: JSON.stringify({ email: state.resetAuth?.email, verificationCode: String(verificationCode).trim(), newPassword }) }); state.resetAuth = null; sessionStorage.setItem('railflow-auth-message', data.message || 'Password reset successfully. Please sign in with your new password.'); location.hash = '#/login'; } catch (err) { if (error) error.textContent = err.message; button.disabled = false; button.textContent = 'Verify code & Reset password'; } });
document.querySelector('#resend-code-btn')?.addEventListener('click', async () => { const button = document.querySelector('#resend-code-btn'); button.disabled = true; button.textContent = 'Resending…'; try { const data = await api('/auth/send-reset-code', { method: 'POST', body: JSON.stringify({ identifier: state.resetAuth?.email }) }); alert(data.message || 'Verification code resent to your Gmail inbox.'); } catch (err) { alert(err.message); } finally { button.disabled = false; button.textContent = 'Resend code'; } });
document.querySelector('#restart-reset-btn')?.addEventListener('click', () => { state.resetAuth = { step: 1, email: '' }; render(); });
document.querySelector('#coach-select')?.addEventListener('change', e => { syncBookingForm(document.querySelector('#booking-form')); state.selectedCoach = e.target.value; render(); });
document.querySelectorAll('[data-seat-map]').forEach(button => button.addEventListener('click', () => { syncBookingForm(document.querySelector('#booking-form')); const seatId = button.dataset.seatMap, selected = state.selectedSeatIds.map(String); if (selected.includes(String(seatId))) state.selectedSeatIds = state.selectedSeatIds.filter(id => String(id) !== String(seatId)); else if (state.selectedSeatIds.length >= 4) { document.querySelector('#booking-error').textContent = 'A purchase can contain at most 4 seats.'; return; } else state.selectedSeatIds.push(seatId); state.coPassengerNames = state.coPassengerNames.slice(0, Math.max(0, state.selectedSeatIds.length - 1)); document.querySelector('#booking-error').textContent = ''; render(); }));
document.querySelector('#booking-form')?.addEventListener('submit', e => { e.preventDefault(); syncBookingForm(e.currentTarget); const error = document.querySelector('#booking-error'); if (!state.selectedSeatIds.length) { error.textContent = 'Select at least one available seat.'; return; } if (state.coPassengerNames.some(name => !name)) { error.textContent = 'Enter every co-passenger name before continuing.'; return; } state.schedule.boarding_stop_id = Number(document.querySelector('#boarding-stop')?.value || state.schedule.boarding_stop_id); location.hash = '#/payment'; });
document.querySelectorAll('input[name="payment"]').forEach(input => input.addEventListener('change', () => { state.payment = input.value; render(); }));
document.querySelectorAll('[data-provider]').forEach(button => button.addEventListener('click', () => { state.mobileProvider = button.dataset.provider; render(); }));
document.querySelector('#complete-booking')?.addEventListener('click', async () => { const button = document.querySelector('#complete-booking'); button.disabled = true; button.textContent = 'Creating ticket…'; try { state.booking = await api('/bookings', { method: 'POST', body: JSON.stringify({ scheduleId: state.schedule.schedule_id, boardingStopId: state.schedule.boarding_stop_id, alightingStopId: state.schedule.alighting_stop_id, paymentMethod: state.payment, passenger: state.purchaser, seatIds: state.selectedSeatIds, coPassengerNames: state.coPassengerNames }) }); location.hash = '#/tickets'; } catch (err) { button.disabled = false; button.textContent = 'Confirm purchase'; alert(err.message); } });
document.querySelector('#cancel-booking')?.addEventListener('click', async e => { const button = e.currentTarget; button.disabled = true; try { const result = await api(`/bookings/${encodeURIComponent(button.dataset.reference)}/cancel`, { method: 'POST', body: JSON.stringify({ reason: 'Change of travel plan' }) }); alert(`Booking cancelled. Fee: ${result.fee_percent}%. Refund: ${cash(result.refund_amount)}`); state.bookingDetails = []; state.booking = null; location.hash = '#/tickets'; } catch (error) { button.disabled = false; alert(error.message); } });
document.querySelector('#cancel-ticket')?.addEventListener('click', async e => { try { const result = await api(`/tickets/${e.currentTarget.dataset.ticket}/cancel`, { method: 'POST', body: JSON.stringify({ reason: document.querySelector('#cancel-reason').value }) }); alert(`Cancellation submitted. Refund: ${cash(result.refund_amount)}`); state.booking.tickets = state.booking.tickets.filter(ticket => ticket.ticket_id !== result.ticket_id); location.hash = '#/tickets'; } catch (err) { alert(err.message); } });
}
function updateDateNavigation(form) { const today = dateInputValue(new Date()), input = form.elements.date, previous = form.querySelector('#previous-day'), next = form.querySelector('#next-day'); if (previous) previous.disabled = input.value <= today; if (next) next.disabled = input.value >= shiftDate(today, 10); }
async function loadSchedules(filters = {}) { const target = document.querySelector('#schedule-results'); if (!target) return; target.innerHTML = notice('Loading available trains…'); try { const params = new URLSearchParams(Object.entries(filters).filter(([, value]) => String(value || '').trim())); state.schedules = await api(`/schedules${params.toString() ? `?${params}` : ''}`); target.innerHTML = state.schedules.length ? `<p class="result-date">Showing trains for ${filters.date}.</p>${state.schedules.map(scheduleRow).join('')}` : `<p class="empty">No trains match those journey details for ${filters.date}. Try another date within the 10-day window.</p>`; bindScheduleButtons(); } catch (err) { target.innerHTML = `<p class="form-error">${err.message}</p>`; } }
function bindScheduleButtons() { document.querySelectorAll('[data-schedule]').forEach(button => button.addEventListener('click', async () => { const schedule = state.schedules.find(s => String(s.schedule_id) === button.dataset.schedule); try { state.schedule = schedule;[state.seats, state.stops, state.fares] = await Promise.all([api(`/schedules/${schedule.schedule_id}/seats`), api(`/schedules/${schedule.schedule_id}/stops`), api(`/schedules/${schedule.schedule_id}/fares`)]); const p = state.profile || {}; state.selectedCoach = state.seats[0]?.coach_no || ''; state.selectedSeatIds = []; state.purchaser = { name: p.name || state.auth.user.name, email: p.email || state.auth.user.email, phone: p.phone || '', age: p.age || '', gender: p.gender || 'Female' }; location.hash = '#/booking'; } catch (err) { alert(err.message); } })); }
async function loadDirectBookingTrains() { if (!location.hash.includes('#/booking') || state.schedule) return; const pageContent = document.querySelector('.page'); if (!pageContent) return; if (!document.querySelector('#booking-suggestions')) pageContent.insertAdjacentHTML('beforeend', '<h3>Available trains today</h3><div id="booking-suggestions">' + notice('Loading available trains…') + '</div>'); try { const rows = await api(`/schedules?date=${dateInputValue(new Date())}`); const target = document.querySelector('#booking-suggestions'); if (target) target.innerHTML = rows.slice(0, 3).map(scheduleRow).join('') || '<p class="empty">No trains are available today. Try Find trains for another date.</p>'; bindScheduleButtons(); } catch (error) { const target = document.querySelector('#booking-suggestions'); if (target) target.innerHTML = `<p class="form-error">${error.message}</p>`; } }
addEventListener('hashchange', render); addEventListener('hashchange', loadDirectBookingTrains); addEventListener('DOMContentLoaded', render); addEventListener('DOMContentLoaded', loadDirectBookingTrains);